const clone=o=>JSON.parse(JSON.stringify(o));
/* ---------- 用户默认设置：每张卡片右下角“设为默认”，存在本机浏览器 ---------- */
// 只保存样式类设置；坐标范围、轴标题、文字内容、年龄等随数据变化的值不保存
const DEF_KEYS={
  color:["paletteId","paletteReverse"],
  data:["sigma","caps","radius","markerAlpha","alpha","edgeColor","edgeWidth","stroke","capSize","numberSize","showOmitted","numbers","ellStroke","ellEdge","ellMarker"],
  axes:["font","tickDir","axisSize","tickSize","frameWidth","tickLen","width","height","grid"],
  text:[...["show","font","size","bold","italic","align","lh","x","y"].flatMap(k=>["title."+k,"note."+k]),"note.auto",...["show","layout","align","font","size","bold","gap","symW","x","y","box","auto","inset","showLine","showOmit","lineLabel","omitLabel"].map(k=>"legend."+k),...["show","text","font","size","bold","italic","corner","where","x","y"].map(k=>"panel."+k)],
  fit:["fit","lineColor","lineStyle","lineWidth","lineExtent","band.show","band.color","band.alpha","band.edgeColor","band.edgeWidth","band.extend"],
  export:["exp.format","exp.dpi","exp.customDpi","exp.bg","exp.embed"]
};
const DEF_STORE="isostyle.defaults.v1";
function readDefaults(){try{return JSON.parse(localStorage.getItem(DEF_STORE))||{}}catch(e){return{}}}
function writeDefaults(d){try{localStorage.setItem(DEF_STORE,JSON.stringify(d));return true}catch(e){return false}}
function setPath(o,k,v){const ps=k.split(".");for(let i=0;i<ps.length-1;i++)o=o[ps[i]];o[ps[ps.length-1]]=v}
function getPath(o,k){return k.split(".").reduce((a,p)=>a==null?a:a[p],o)}
// 程序自带设置 + 用户保存的默认设置
