  const L=[];
  if(age)L.push("Age = "+age[1]+" ± "+age[2]+(age[3]?" | "+age[3]:"")+(age[4]?" | "+age[4]:"")+" "+age[5]+(cnt?" (n = "+cnt[1]+")":""));
  if(ic)L.push("INITIAL = "+ic[1]+(ic[2]?" ± "+ic[2]:"")+(ic[3]?" | "+ic[3]:""));
  if(ms)L.push("MSWD = "+ms[1]+(pr?"; p(χ^{2}) "+pr[1]+" "+pr[2]:""));
