      const t=textBlock(L.join("\n"),{x:ax,y:ay,fam:fam("inherit"),size:sz,align:right?"end":"start",lh:1.25,fill:a.color});
      const p2=2.5,B={x:t.box.x-p2,y:t.box.y-p2,w:t.box.w+2*p2,h:t.box.h+2*p2};
