      const lead=dd>r0+1?line(P.x+(qx-P.x)/dd*r0,P.y+(qy-P.y)/dd*r0,qx,qy,a.color,.4):"";
      const fr=a.box!==false?`<rect x="${r2(B.x)}" y="${r2(B.y)}" width="${r2(B.w)}" height="${r2(B.h)}" fill="#ffffff" fill-opacity=".92" stroke="${a.color}" stroke-width=".4"/>`:"";
