    h+=`<div class="r"><div class="field">线型${STYLE_SEG(k("style"))}</div></div>`;
    h+=`<div class="r">${fText(k("label"),"名称（可空）","例如 初始比值")}${fNum(k("size"),"字号 (pt)",3,40,.5,"w-num")}</div>`;
