    if(a.mode==="age"&&kind){h+=`<div class="r">${fNum(k("age"),"年龄 (Ma)","","","","w-coord")}${kind==="decay"?fNum(k("r0"),"初始比值","","","","w-coord"):""}</div>`;
      if(kind==="pbpb")h+=`<p class="hint">初始 Pb 用 JSON 里的 ²⁰⁶Pb/²⁰⁴Pb = ${iratio("Pb206Pb204")}、²⁰⁷Pb/²⁰⁴Pb = ${iratio("Pb207Pb204")}。</p>`}
