$("#annPopClose").onclick=()=>annSelect(null);
$("#annProps").addEventListener("click",e=>{const d=e.target.closest("[data-ann-del]");if(d)delAnn(+d.dataset.annDel)});

/* ---------- 图上的交互：框选放大、拖动文字与标注、放置标注、悬停 ---------- */
let act=null;
function svgPt(e,svg){const p=new window.DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());return{x:p.x,y:p.y}}
const paper=$("#paper");
paper.addEventListener("pointerdown",e=>{
  const svg=paper.querySelector("svg");if(!svg||e.button!==0||!dims)return;
  hideTip();const q=svgPt(e,svg);
  if(tool!=="select"){e.preventDefault();
    if(tool==="line"||tool==="arrow"){const l=document.createElementNS(NS,"line");l.setAttribute("class","zline");for(const [k,v] of [["x1",q.x],["y1",q.y],["x2",q.x],["y2",q.y]])l.setAttribute(k,v);svg.appendChild(l);act={kind:"newline",start:q,end:q,el:l};paper.setPointerCapture(e.pointerId)}
    else placeAnn(tool,q,e);
    return}
  const h=e.target.closest("[data-annh]"),an=e.target.closest("[data-ann]"),dr=e.target.closest("[data-drag]");
  if(h){const [id,end]=h.dataset.annh.split(":");act={kind:"ann",id:+id,end,cx:e.clientX,cy:e.clientY,orig:clone(annById(+id)),sc:scale,moved:false}}
  else if(an){const id=+an.dataset.ann;act={kind:"ann",id,end:null,cx:e.clientX,cy:e.clientY,orig:clone(annById(id)),sc:scale,moved:false}}
  else if(dr){act={kind:"drag",el:dr,what:dr.dataset.drag,start:q,d:{x:0,y:0},moved:false}}
  else if(q.x>=0&&q.x<=dims.pw&&q.y>=0&&q.y<=dims.ph){
    const r=document.createElementNS(NS,"rect");r.setAttribute("class","zrect");svg.appendChild(r);
    act={kind:"zoom",start:q,end:q,rect:r};
  }else{select(null);if(annSel)annSelect(null);return}
  e.preventDefault();paper.setPointerCapture(e.pointerId);
});
// 拖动标注：按屏幕位移换算成 pt，再换算成数据坐标
function moveAnn(A,dx,dy){
  const a=annById(A.id),o=A.orig;if(!a)return;const kx=(S.xmax-S.xmin)/dims.pw,ky=(S.ymax-S.ymin)/dims.ph;
  if(a.type==="text"){a.x=sig(o.x+dx*kx);a.y=sig(o.y-dy*ky)}
  else if(a.type==="line"){if(A.end!=="2"){a.x1=sig(o.x1+dx*kx);a.y1=sig(o.y1-dy*ky)}if(A.end!=="1"){a.x2=sig(o.x2+dx*kx);a.y2=sig(o.y2-dy*ky)}}
  else if(a.type==="hline")a.v=sig(o.v-dy*ky);
  else if(a.type==="vline")a.v=sig(o.v+dx*kx);
  else if(a.type==="pt"){a.dx=r2(o.dx+dx);a.dy=r2(o.dy+dy)}
  else if(a.type==="iso"){const c=dims.annSeg[a.id];if(c){const ux=c[2]-c[0],uy=c[3]-c[1],L2=ux*ux+uy*uy||1;a.lt=r2(Math.max(0,Math.min(1,(o.lt??.82)+(dx*ux+dy*uy)/L2)))}}
}
paper.addEventListener("pointermove",e=>{
  const svg=paper.querySelector("svg");if(!svg||!dims)return;
  if(act){
    if(act.kind==="ann"){const dx=(e.clientX-act.cx)/act.sc,dy=(e.clientY-act.cy)/act.sc;if(!act.moved&&Math.hypot(dx,dy)*act.sc>3){act.moved=true;if(annSel!==act.id){annSel=act.id;renderAnn()}}
      if(act.moved){moveAnn(act,dx,dy);quietDraw++;try{draw()}finally{quietDraw--}}return}
    const q=svgPt(e,svg);
    if(act.kind==="newline"){act.end=q;act.el.setAttribute("x2",q.x);act.el.setAttribute("y2",q.y);return}
    if(act.kind==="zoom"){const c={x:Math.max(0,Math.min(dims.pw,q.x)),y:Math.max(0,Math.min(dims.ph,q.y))};act.end=c;const a=act.start;
      act.rect.setAttribute("x",Math.min(a.x,c.x));act.rect.setAttribute("y",Math.min(a.y,c.y));act.rect.setAttribute("width",Math.abs(a.x-c.x));act.rect.setAttribute("height",Math.abs(a.y-c.y))}
    else{act.d={x:q.x-act.start.x,y:q.y-act.start.y};if(Math.hypot(act.d.x,act.d.y)*scale>3)act.moved=true;act.el.setAttribute("transform",`translate(${r2(act.d.x)} ${r2(act.d.y)})`)}
    return}
  const g=e.target.closest("[data-pt]");if(g){showTip(e,+g.dataset.pt);hoverPt(+g.dataset.pt,g)}else{hideTip();hoverPt(null)}
});
function endAct(e,cancel){
  const svg=paper.querySelector("svg");if(!act)return;const a=act;act=null;
  if(e&&paper.hasPointerCapture(e.pointerId))paper.releasePointerCapture(e.pointerId);
  if(a.kind==="newline"){a.el.remove();if(cancel)return;
    let p=a.start,q=a.end;if(Math.hypot(q.x-p.x,q.y-p.y)*scale<6)q={x:p.x+40,y:p.y-24};
    const fx=x=>sig(S.xmin+x/dims.pw*(S.xmax-S.xmin)),fy=y=>sig(S.ymax-y/dims.ph*(S.ymax-S.ymin));
    const n=addAnn(Object.assign({type:"line",x1:fx(p.x),y1:fy(p.y),x2:fx(q.x),y2:fy(q.y),arrow:tool==="arrow"?"end":"none"},LINE_DEF()));
    setTool("select");annSelect(n.id,true);draw();return}
  if(a.kind==="ann"){
    if(cancel){const i=(S.ann||[]).findIndex(x=>x.id===a.id);if(i>=0)S.ann[i]=a.orig;draw();return}
    if(!a.moved){annSelect(a.id,true);return}
    renderAnnList();syncControls();draw();return}
  if(a.kind==="zoom"){a.rect.remove();if(cancel)return;
    const p=a.start,q=a.end;
    if(Math.abs(p.x-q.x)*scale>6&&Math.abs(p.y-q.y)*scale>6){
      const fx=x=>S.xmin+x/dims.pw*(S.xmax-S.xmin),fy=y=>S.ymax-y/dims.ph*(S.ymax-S.ymin);
      history.push(rangeNow());setRange(fx(Math.min(p.x,q.x)),fx(Math.max(p.x,q.x)),fy(Math.max(p.y,q.y)),fy(Math.min(p.y,q.y)),true);syncControls();draw();
    }else if(annSel)annSelect(null)}
  else{
    if(cancel){a.el.removeAttribute("transform");return}
    if(!a.moved){select(a.what,true);return}
    const o=S[a.what];o.x=r2(o.x+a.d.x/dims.pw*100);o.y=r2(o.y+a.d.y/dims.ph*100);if(a.what==="legend"||a.what==="note")o.auto=false;selected=a.what;syncControls();draw();
  }
}
