const fmtV=v=>Number.isFinite(v)?String(+v.toPrecision(8)):"—";
function showTip(e,id){
  const p=points.find(q=>q.id===id);if(!p)return;const g=groups[p.group],u=["","1σ","2σ","1σ %","2σ %"][meta.ierr];
  const t=$("#tip");
  t.innerHTML=`<b><i style="background:${p.omit?OMIT_COLOR:g.color}"></i>第 ${p.id} 行 · ${esc(g.name)}</b><div class="tr"><span>X</span><span>${fmtV(p.x)} ± ${fmtV(p.ex)}</span><span>Y</span><span>${fmtV(p.y)} ± ${fmtV(p.ey)}</span><span>ρ</span><span>${p.rho===null?"无（画成十字）":fmtV(p.rho)}</span><span>误差</span><span>输入 ${u}，图示 ±${S.sigma}σ</span></div>`+(p.comment?`<div class="cm">注释：<span class="noi18n">${esc(p.comment)}</span></div>`:"")+(p.omit?`<div class="ex">已剔除</div>`:"");
  t.hidden=false;const w=t.offsetWidth,h=t.offsetHeight;
  t.style.left=Math.min(e.clientX+14,window.innerWidth-w-8)+"px";t.style.top=Math.max(8,e.clientY+16+h>window.innerHeight?e.clientY-h-12:e.clientY+16)+"px";FIXPOS(t);
}
function hideTip(){$("#tip").hidden=true}
// 悬停的数据点：保留组颜色，线条加粗、填充加深并提到最上层；其他点淡到 55%（只在屏幕上，导出时还原）
let hovId=null;
function hoverPt(id,g){
  const svg=paper.querySelector("svg");if(!svg)return;
  const cur=svg.querySelector("[data-pt].hov");if(id===hovId&&cur)return;
  if(cur){cur.classList.remove("hov");cur.querySelectorAll("[data-hsw],[data-hfo]").forEach(e=>{if(e.dataset.hsw!==undefined){e.setAttribute("stroke-width",e.dataset.hsw);delete e.dataset.hsw}if(e.dataset.hfo!==undefined){e.setAttribute("fill-opacity",e.dataset.hfo);delete e.dataset.hfo}})}
  svg.classList.remove("dim");hovId=id;if(id===null)return;
  g=g||svg.querySelector(`[data-pt="${id}"]`);if(!g)return;
  for(const e of g.querySelectorAll("*")){if(e.classList.contains("hit"))continue;
    const w=e.getAttribute("stroke-width");if(w&&e.getAttribute("stroke")&&e.getAttribute("stroke")!=="none"){e.dataset.hsw=w;e.setAttribute("stroke-width",r2(+w*2.2))}
    const fo=e.getAttribute("fill-opacity");if(fo&&+fo<1){e.dataset.hfo=fo;e.setAttribute("fill-opacity",r2(Math.min(1,+fo*2)))}}
  g.classList.add("hov");g.parentNode.appendChild(g);svg.classList.add("dim");
}
$("#backBtn").onclick=()=>{const r=history.pop();if(r){Object.assign(S,r);syncControls();draw()}};
