  $("#tBody").innerHTML=points.map(p=>{const g=groups[p.group];return `<tr data-id="${p.id}" class="${p.omit?"omit":""}"><td class="n">${p.id}</td><td class="n">${fmtV(p.x)}</td><td class="n">${fmtV(p.ex)}</td><td class="n">${fmtV(p.y)}</td><td class="n">${fmtV(p.ey)}</td><td class="n">${p.rho===null?"—":fmtV(p.rho)}</td><td><span class="gc noi18n"><i style="background:${g.color}"></i>${esc(g.name)}</span></td><td class="cm">${esc(p.comment)}</td><td class="st">${p.omit?"剔除":"保留"}</td></tr>`}).join("");
