/* ---------- 控件绑定 ---------- */
const RANGE_KEYS=["xmin","xmax","ymin","ymax"];
// 不透明度在界面上用百分比显示，内部仍存 0–1
const PCT_KEYS=new Set(["alpha","markerAlpha","band.alpha"]);
function fmtInput(v){if(v===""||v===null||v===undefined)return"";const n=Number(v);return Number.isFinite(n)?String(+n.toPrecision(10)):String(v)}
function syncControls(){
  for(const el of $$("[data-k]")){
    const v=getK(el.dataset.k);
    if(el.classList.contains("seg"))el.querySelectorAll("button").forEach(b=>b.classList.toggle("on",String(b.dataset.v)===String(v)));
    else if(el.type==="checkbox")el.checked=!!v;
    else if(el.type==="number"){if(ROOT.activeElement!==el)el.value=PCT_KEYS.has(el.dataset.k)?String(Math.round(v*1000)/10):fmtInput(v);el.classList.remove("bad");el.closest(".num")&&el.closest(".num").classList.remove("bad")}
    else if(ROOT.activeElement!==el||el.tagName==="SELECT")el.value=v===true?"true":v===false?"false":(v??"");
  }
  for(const b of $$("[data-tk]"))b.classList.toggle("on",!!getK(b.dataset.tk));
  for(const el of $$(".rich[data-rk]"))if(ROOT.activeElement!==el){const h=markupToHTML(normalizeMarkup(getK(el.dataset.rk)??""));if(el.innerHTML!==h)el.innerHTML=h}
  const oc=$("#orientCtl");if(oc)oc.hidden=!raw||dataInverse()===null;
  showTab(textTab,true);
  if(typeof updateOff==="function")updateOff();
  for(const b of $$("[data-color-k]")){const c=getK(b.dataset.colorK),i=b.querySelector("i");i.className=c==="same"?"same":"";i.style.background=c==="same"?"":c;b.querySelector("span").textContent=colorName(c)}
  const vector=S.exp.format==="pdf"||S.exp.format==="svg",canAlpha=["png","webp","svg"].includes(S.exp.format);
  $("#dpiField").hidden=vector;$("#customDpiField").hidden=vector||S.exp.dpi!=="custom";
  $("#bgField").hidden=!canAlpha;$("#embedField").hidden=S.exp.format!=="svg";
  $("#expBtn").textContent="导出 "+{pdf:"PDF",svg:"SVG",png:"PNG",tiff:"TIFF",jpeg:"JPEG",webp:"WebP",bmp:"BMP"}[S.exp.format];
  $("#exportCard select").title="格式";
}
function colorName(c){
  if(c==="same")return"与填充同色";
  if(String(c).toUpperCase()==="#CCCCCC")return"浅灰（IsoplotR 原图）";
  const C=String(c).toUpperCase();if(C==="#FFFFFF")return"白色";
  for(const p of PALETTES)if(p.c){const i=p.c.indexOf(C);if(i>=0)return `${p.name} · 第 ${i+1} 色`}
  if(NEUTRALS.includes(C))return"中性灰";
  for(const g of order)if(groups[g].color.toUpperCase()===C)return groups[g].name+" 同色";
  return"色板颜色";
}
function onInput(el){
  const k=el.dataset.k;let v;
  if(el.type==="checkbox")v=el.checked;
  else if(el.type==="number"){
    if(el.value.trim()===""){if(["age","lambda","slope","intercept","exp.customDpi"].includes(k))v="";else return}
    else{v=Number(el.value);const bad=!Number.isFinite(v)||(el.min!==""&&v<+el.min)||(el.max!==""&&v>+el.max);(el.closest(".num")||el).classList.toggle("bad",bad);if(bad)return;if(PCT_KEYS.has(k))v=v/100}
  }else v=el.tagName==="SELECT"&&(el.value==="true"||el.value==="false")?el.value==="true":el.value;
  setK(k,v);afterChange(k);
}
function afterChange(k){
  if(!k.startsWith("exp."))markDirty();
  if(k==="paletteReverse"){applyPalette();return}
  if(k.startsWith("panel.")&&["panel.corner","panel.where","panel.size","panel.text"].includes(k))placePanel=true;
  if(k==="exp.dpi"&&S.exp.dpi==="custom"&&!S.exp.customDpi)S.exp.customDpi=600;
  if(k==="font"||k.startsWith("exp."))syncControls();
  if(k==="exp.customDpi")syncControls();
  if(k==="sigma"&&false)autoscale(false);
  if(k==="fitMode")syncControls();
  if(k==="inverse"){applyOrientation();[S.xLabel,S.yLabel]=autoTitles();setupLine();history=[];renderTable();syncControls();autoscale(false);return}
  if(k==="legend.x"||k==="legend.y"||k==="note.x"||k==="note.y"){const g=k.split(".")[0];S[g].auto=false;const c=ROOT.querySelector(`[data-k="${g}.auto"]`);if(c)c.checked=false}
  if(k==="note.auto"&&S.note.auto)syncControls();
  if(k==="legend.auto"&&S.legend.auto)syncControls();
  if(k.startsWith("ann.")&&/\.age$/.test(k)){const a=S.ann[+k.split(".")[1]];if(a&&/^\s*([-+\d.eE]+\s*Ma)?\s*$/.test(String(a.label||""))){a.label=num(a.age)!==null?a.age+" Ma":"";const el=ROOT.querySelector(`[data-k="ann.${k.split(".")[1]}.label"]`);if(el)el.value=a.label}}
  if(k.startsWith("ann.")){if(/\.mode$/.test(k)){const a=S.ann[+k.split(".")[1]];if(a&&a.mode==="age"&&!String(a.label||"").trim())a.label=a.age+" Ma";renderAnnProps()}else renderAnnList()}
  if(k.startsWith("exp."))return updateExportSize();
  scheduleDraw();
}
let drawQ=0;function scheduleDraw(){cancelAnimationFrame(drawQ);drawQ=requestAnimationFrame(()=>draw())}
