KEYDOC(e=>{const el=e.target;if(el.matches&&el.matches("input[type=number][data-k]")&&(e.key==="ArrowUp"||e.key==="ArrowDown")){e.preventDefault();stepInput(el,e.key==="ArrowUp"?1:-1)}});
function stepInput(input,dir){
  const k=input.dataset.k;let step=input.step&&input.step!=="any"?Number(input.step):null;
  if(step===null){
    if(k==="xmin"||k==="xmax")step=S.xstep/2;else if(k==="ymin"||k==="ymax")step=S.ystep/2;
    else if(k==="xstep"||k==="ystep"){const v=Math.abs(Number(input.value))||1;step=niceStep(v*5)/5}
    else{const v=Math.abs(Number(input.value))||1;step=10**(Math.floor(Math.log10(v))-1)}
  }
  let v=(Number(input.value)||0)+dir*step;
  if(input.min!=="")v=Math.max(+input.min,v);if(input.max!=="")v=Math.min(+input.max,v);
  input.value=+v.toPrecision(10);onInput(input);
}
const palClose=()=>{$("#palAll").hidden=true;$("#palCur").setAttribute("aria-expanded",false)};
