/* ---------- 载入 ---------- */
function installResult(r){
  pdfResult=r;
  S.note.text=(r&&r.annotation||"").replace("INITIAL","("+isotope(FY)+")_{0}");
  S.age=r&&r.age!=null?r.age:"";S.intercept=r&&r.intercept!=null?r.intercept:"";
  setupLine();
}
// 等时线参数：优先用 PDF（与当前坐标方向一致时）；没有可用的结果时用 York 回归
function setupLine(){
  const r=pdfMatches()?pdfResult:null,sys=ageSystem(),Y=yorkFit=york(points);S.lineSrc="pdf";
  if(r){S.age=r.age!=null?r.age:"";S.intercept=r.intercept!=null?r.intercept:""}else{S.age="";S.intercept="";S.slope=""}
  if(sys){const lam=raw.constants&&raw.constants.lambda&&raw.constants.lambda[sys[2]];S.lambda=lam?lam[0]:"";S.fitMode="age";
    if((num(S.age)===null||num(S.intercept)===null)&&Y&&num(S.lambda)>0&&Y.b>-1){S.age=+(Math.log1p(Y.b)/S.lambda).toPrecision(8);S.intercept=+Y.a.toPrecision(8);S.lineSrc="york"}
    S.fit=num(S.age)!==null&&num(S.intercept)!==null&&num(S.lambda)!==null}
  else if(r&&r.slope!=null&&r.intercept!=null){S.slope=r.slope;S.fitMode="slope";S.fit=true}
  else if(r&&r.pline){S.slope=+r.pline.m.toPrecision(8);S.intercept=r.intercept!=null?r.intercept:+r.pline.b.toPrecision(8);S.fitMode="slope";S.fit=true}
  else if(Y){S.slope=+Y.b.toPrecision(8);S.intercept=+Y.a.toPrecision(8);S.fitMode="slope";S.fit=true;S.lineSrc="york"}
  else{S.fit=false;S.fitMode="slope"}
}
// 当前方向下的轴标题：和 PDF 方向一致时用 PDF 里的标题，否则由列名推出
function autoTitles(){
  if(pdfMatches()&&pdfResult.titles&&pdfResult.titles.x&&pdfResult.titles.y)return[pdfResult.titles.x,pdfResult.titles.y];
  const tx=isotope(FX),ty=isotope(FY);if(!flipped())return[tx,ty];
  const X=tx.split("/"),Y=ty.split("/");if(X.length!==2||Y.length!==2)return[tx,ty];
  return meta.sys==="Pb-Pb"?[X[1]+"/"+X[0],Y[0]+"/"+X[0]]:[X[0]+"/"+Y[0],Y[1]+"/"+Y[0]];
}
function applyOrientation(){points=flipped()?flipPoints(basePts,meta.sys):basePts}
function loadData(j,r,name,opts={}){quietDraw++;try{loadDataInner(j,r,name,opts)}finally{quietDraw--}setDirty(false,!!j.isoStyle);resetUndo()}
function loadDataInner(j,r,name,opts={}){
  const project=j.isoStyle?j:null,data=project?project.data:j,m=inspectData(data);
  const af=autoFields(m),x=project&&project.fields&&m.keys.includes(project.fields.x)?project.fields.x:af[0],y=project&&project.fields&&m.keys.includes(project.fields.y)?project.fields.y:af[1];
  const ps=parsePoints(m,x,y);
  raw=data;meta=m;points=ps;basePts=ps;history=[];selected=null;annSel=null;
  FX=x;FY=y;
  if(project&&project.isoStyle>=3){const B0=baseState();S=Object.assign(B0,project.S||{});for(const k of ["title","note","legend","panel","exp","band"])S[k]=Object.assign(clone(B0[k]),(project.S||{})[k]||{});if(!Array.isArray(S.ann))S.ann=[];if(S.inverse===undefined)S.inverse=!!dataInverse();pdfResult=project.pdfResult||null;placePanel=false;applyOrientation();yorkFit=york(points)}
  else{
    const keepExp=S.exp;S=baseState();S.exp=keepExp;
    // 方向：以 PDF 原图的坐标轴为准；没有 PDF 时按 JSON 的 inverse 设置
    if(r)r.inv=r.titles&&r.titles.x&&r.titles.y?orientOf(m.sys,r.titles.x,r.titles.y):null;
    const dInv=orientOf(m.sys,isotope(x,m.sys),isotope(y,m.sys));
    S.inverse=dInv===null?false:(r&&r.inv!==null&&r.inv!==undefined?r.inv:!!m.inverse);
    pdfResult=r;applyOrientation();
    [S.xLabel,S.yLabel]=autoTitles();
    S.title.text=opts.title||(name?name.replace(/\.(pdf|json)$/i,""):m.sys+" isochron");
    if(project)migrateV2(project);else installResult(r);
    // 椭圆数据：等时线默认 0.5 pt 实线（用户在“等时线”卡片设过默认值时以用户的为准）
    if(ps.some(p=>p.rho!==null)&&!(readDefaults().fit)){S.lineStyle="solid";S.lineWidth=.5}
    placePanel=true;
  }
  source=project?project.source||"":name||"";
  if(!project)S.exp.name=defaultFileName();
  setupGroups(project?project.groups:{},project?project.order:[]);
  setTool("select");
  renderGroups();renderPalettes();renderTable();renderAnn();syncControls();
  if(project||opts.keepRange)draw();else autoscale(false);
}
// 旧版（v2）项目文件
function migrateV2(p){
  const c=p.controls||{},n=v=>v===undefined?undefined:Number(v);
  const map={tickSize:"tickSize",axisSize:"axisSize",stroke:"stroke",frameWidth:"frameWidth",marker:"marker",radius:"radius",sigma:"sigma",alpha:"alpha",caps:"caps",omitted:"showOmitted",numbers:"numbers",xLabel:"xLabel",yLabel:"yLabel",xmin:"xmin",xmax:"xmax",ymin:"ymin",ymax:"ymax",xstep:"xstep",ystep:"ystep",xdigits:"xdigits",ydigits:"ydigits",width:"width",height:"height",grid:"grid",fit:"fit",fitMode:"fitMode",age:"age",lambda:"lambda",slope:"slope",intercept:"intercept",lineStyle:"lineStyle",lineWidth:"lineWidth",paletteId:"paletteId",paletteReverse:"paletteReverse"};
  for(const [a,b] of Object.entries(map))if(c[a]!==undefined)S[b]=typeof DEF[b]==="number"?n(c[a]):c[a];
  if(c.lineColor)S.lineColor=c.lineColor;
  const tx={title:"title",note:"note",legend:"legend"};
  for(const [a,b] of Object.entries(tx)){for(const f of ["Size","Bold","Align","X","Y","Show"]){const v=c[a+f];if(v!==undefined)S[b][f.toLowerCase()]=f==="Bold"||f==="Show"?!!v:f==="Align"?v:Number(v)}}
  if(c.title!==undefined)S.title.text=c.title;if(c.annotation!==undefined)S.note.text=c.annotation;
  if(c.legendVertical)S.legend.layout="col";
  if(c.panelShow!==undefined){S.panel.show=!!c.panelShow;S.panel.text=c.panelText||"A";S.panel.corner=c.panelCorner||"tl";S.panel.size=n(c.panelSize)||14;S.panel.bold=!!c.panelBold}
  pdfResult=p.pdfResult||null;
}
function showFiles(list){files=list;$("#fileList").innerHTML=list.map(f=>`<li><span class="ext ${f.ext}">${f.ext.toUpperCase()}</span><span class="fn" title="${esc(f.name)}">${esc(f.name)}</span></li>`).join("")}
function showReference(bytes){
  const box=$("#refBody");
  if(!bytes){box.innerHTML=`<p class="note">没有原始 PDF（只导入了 JSON，或项目文件里没有附带）。</p>`;return}
  box.innerHTML=`<p class="note">正在显示原始 PDF…</p>`;
  // 用内置 PDF.js 把第一页画成图片；不用 blob 地址，在受限的预览环境里也能显示
  (async()=>{try{const mod=await getPDFjs(),doc=await mod.getDocument({data:bytes.slice(),useSystemFonts:true,isEvalSupported:false,verbosity:0}).promise;
    try{const page=await doc.getPage(1),vp=page.getViewport({scale:2}),cv=document.createElement("canvas");cv.width=Math.ceil(vp.width);cv.height=Math.ceil(vp.height);
      await page.render({canvasContext:cv.getContext("2d"),viewport:vp}).promise;
      cv.className="ref-canvas";box.replaceChildren(cv);
      if(doc.numPages>1){const n=document.createElement("p");n.className="note";n.textContent=`只显示第 1 页（共 ${doc.numPages} 页）。`;box.appendChild(n)}
    }finally{await doc.destroy()}
  }catch(e){box.innerHTML=`<p class="note">无法显示原始 PDF：${esc(e.message)}</p>`}})();
}
let importSerial=0;
async function importFiles(list){
  const serial=++importSerial;list=[...list];if(!list.length)return;importNote="";
  try{
    const js=list.filter(f=>/\.json$/i.test(f.name)),pdfs=list.filter(f=>/\.pdf$/i.test(f.name));
    if(js.length!==1)throw Error(js.length?"一次只能导入一个 JSON。":"需要一个 IsoplotR JSON（和对应的 PDF 一起选中）。");
    if(pdfs.length>1)throw Error("一次只能导入一个 PDF。");
    const j=JSON.parse(await js[0].text());
    if(j.isoStyle){
      jsonName=j.jsonName||js[0].name.replace(/\.json$/i,"").replace(/^IsoStyle_/,"").replace(/_(\d{6}|project)$/,"");
      loadData(j,null,"");pdfBytes=j.pdfBytes?b64ToBytes(j.pdfBytes):null;showReference(pdfBytes);
      if(pdfBytes&&pdfResult&&!pdfResult.band)readPDF(pdfBytes).then(r=>{if(r.band){pdfResult.band=r.band;pdfResult.pline=r.pline;quietDraw++;try{draw()}finally{quietDraw--}}}).catch(()=>{});
      showFiles([{name:js[0].name,ext:"json"}]);hdr(`已打开项目 ${js[0].name}`);return;
    }
    inspectData(j);jsonName=js[0].name.replace(/\.json$/i,"");
    let r=null,bytes=null;
    if(pdfs.length){hdr("正在读取 JSON 和 PDF…");bytes=new Uint8Array(await pdfs[0].arrayBuffer());r=await readPDF(bytes)}
    if(serial!==importSerial)return;
    loadData(j,r,(pdfs[0]||js[0]).name);pdfBytes=bytes;showReference(bytes);
    showFiles([{name:js[0].name,ext:"json"},...pdfs.map(f=>({name:f.name,ext:"pdf"}))]);
    if(!pdfs.length){importNote="只导入了 JSON：结果文字和等时线参数需要手动填写（建议把对应的 PDF 一起选中）。";quietDraw++;try{draw()}finally{quietDraw--}}
    else if(!r.annotation){importNote="PDF 里没有识别到结果文字，请在“年龄 / 结果信息”里填写；数据已导入。";quietDraw++;try{draw()}finally{quietDraw--}}
    else if(!S.fit){importNote="已导入数据和结果；这组坐标需要手动填写斜率和截距才能显示等时线。";quietDraw++;try{draw()}finally{quietDraw--}}
    hdr("已导入");
  }catch(err){showMsg(err.message,true);hdr("")}
}
// 保存状态：刚导入（不显示）/ 有未保存更改 / 已保存
let dirty=false,quietDraw=0;
function setDirty(v,saved){dirty=v;const el=$("#saveState");if(!raw||(!v&&!saved)){el.textContent="";el.className="save-state";return}el.textContent=v?"有未保存更改":"已保存";el.className="save-state "+(v?"dirty":"clean")}
function markDirty(){if(raw&&!dirty)setDirty(true)}
window.addEventListener("beforeunload",e=>{if(dirty&&raw){e.preventDefault();e.returnValue=""}});
function hdr(t){$("#hdrMsg").textContent=t;clearTimeout(hdr.t);if(t)hdr.t=setTimeout(()=>$("#hdrMsg").textContent="",4000)}
$("#fileIn").addEventListener("change",e=>{const fs=[...e.target.files];e.target.value="";importFiles(fs)});
for(const zone of [$("#drop"),$("#paperWrap")]){
  zone.addEventListener("dragover",e=>{if([...e.dataTransfer.types].includes("Files")){e.preventDefault();zone.classList.add("over")}});
  zone.addEventListener("dragleave",()=>zone.classList.remove("over"));
  zone.addEventListener("drop",e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();zone.classList.remove("over");importFiles(e.dataTransfer.files)});
}


/* ---------- 导出 ---------- */
function usedFonts(svgText){
  const used=new Set();const re=/font-family="(Iso\w+)"[^>]*font-weight="(bold|normal)"[^>]*font-style="(italic|normal)"/g;let m;
  while((m=re.exec(svgText)))used.add(m[1]+"|"+styleKey(m[2]==="bold",m[3]==="italic"));
  // tspan 里单独切换的斜体
  if(/<tspan[^>]*font-style="italic"/.test(svgText))for(const u of [...used]){const [f,s]=u.split("|");used.add(f+"|"+(s.includes("bold")?"bolditalic":"italic"))}
  if(/<tspan[^>]*font-style="normal"/.test(svgText))for(const u of [...used]){const [f,s]=u.split("|");used.add(f+"|"+(s.includes("bold")?"bold":"normal"))}
  return[...used].map(u=>{const [f,s]=u.split("|");return{fam:Object.keys(FAMILY).find(k=>FAMILY[k]===f),s}});
}
function cleanSVG(){
  const svg=paper.querySelector("svg");if(!svg)throw Error("还没有图形。");
  const c=svg.cloneNode(true);
  c.querySelectorAll(".hit,.hb,.hl,.zrect,.zline,.hdl").forEach(n=>n.remove());
  c.querySelectorAll("[data-hsw]").forEach(e=>e.setAttribute("stroke-width",e.dataset.hsw));c.querySelectorAll("[data-hfo]").forEach(e=>e.setAttribute("fill-opacity",e.dataset.hfo));
  c.querySelectorAll("[data-hsw],[data-hfo]").forEach(e=>{e.removeAttribute("data-hsw");e.removeAttribute("data-hfo")});
  c.querySelectorAll("[data-pt],[data-drag],[data-ann]").forEach(n=>{n.removeAttribute("data-pt");n.removeAttribute("data-drag");n.removeAttribute("data-ann");n.removeAttribute("class")});
  c.querySelectorAll("[class]").forEach(n=>{if(n.getAttribute("class")!=="bg")n.removeAttribute("class")});
  c.removeAttribute("data-w");c.removeAttribute("data-h");c.removeAttribute("class");
  return c;
}
function exportSVGText(withFonts,bg){
  const c=cleanSVG();c.setAttribute("width",r2(dims.W/PT_MM)+"mm");c.setAttribute("height",r2(dims.H/PT_MM)+"mm");
  if(bg==="none")c.querySelectorAll(".bg").forEach(n=>n.remove());else c.querySelectorAll(".bg").forEach(n=>n.removeAttribute("class"));
  let t=new XMLSerializer().serializeToString(c);
  const fonts=usedFonts(t);
  if(withFonts){const css=fonts.map(f=>`@font-face{font-family:'${FAMILY[f.fam]}';font-weight:${f.s.includes("bold")?700:400};font-style:${f.s.includes("italic")?"italic":"normal"};src:url(data:font/ttf;base64,${fontB64(f.fam,f.s)}) format('truetype')}`).join("");
    t=t.replace(/(<svg[^>]*>)/,`$1<style>${css}</style>`)}
  for(const [k,v] of Object.entries(FAMILY))t=t.split(`font-family="${v}"`).join(`font-family="${withFonts?`'${v}', `:""}${EXPORT_FAMILY[k]}"`);
  return t;
}
function dpi(){const d=S.exp.dpi==="custom"?num(S.exp.customDpi):Number(S.exp.dpi);if(!Number.isFinite(d)||d<72||d>2400)throw Error("DPI 应在 72–2400 之间。");return Math.round(d)}
function updateExportSize(){
  const el=$("#expSize");if(!dims){el.textContent="";$("#figFoot").textContent="";$("#expBtn").title="还没有图形";return}
  try{const f=S.exp.format,vec=f==="pdf"||f==="svg",mm0=`${(dims.W/PT_MM).toFixed(1)} × ${(dims.H/PT_MM).toFixed(1)} mm`;
    $("#figFoot").textContent=`成图 ${mm0} · ${f.toUpperCase()} · `+(vec?"矢量":dpi()+" DPI")+(["png","webp","svg"].includes(f)&&S.exp.bg==="none"?" · 透明背景":"")}catch(e){$("#figFoot").textContent=""}
  try{const f=S.exp.format,mm=`${(dims.W/PT_MM).toFixed(1)} × ${(dims.H/PT_MM).toFixed(1)} mm`;
    const bgT=["png","webp","svg"].includes(f)?(S.exp.bg==="none"?" · 透明背景":" · 白色背景"):"";
    if(f==="pdf"||f==="svg"){el.textContent=`成图尺寸 ${mm} · 矢量`;$("#expBtn").title=`${f.toUpperCase()} · 矢量${bgT}${f==="svg"?(S.exp.embed===false?" · 不嵌入字体":" · 嵌入字体"):""} · 成图尺寸 ${mm}\n文件名：${baseName()}.${f}`}
    else{const d=dpi(),px=`${Math.round(dims.W/72*d)} × ${Math.round(dims.H/72*d)} 像素`;el.textContent=`成图尺寸 ${mm} · ${px}`;$("#expBtn").title=`${f.toUpperCase()} · ${d} DPI${bgT} · 成图尺寸 ${mm}（${px}）\n文件名：${baseName()}.${f==="jpeg"?"jpg":f==="tiff"?"tif":f}`}
  }catch(e){el.textContent=e.message}
}
async function rasterCanvas(d,transparent){
  const w=Math.round(dims.W/72*d),h=Math.round(dims.H/72*d);
  if(w*h>80e6)throw Error("图像超过 8000 万像素，请降低 DPI 或缩小数据框。");
  const t=exportSVGText(true,transparent?"none":"white").replace(/width="[^"]+mm"/,`width="${w}"`).replace(/height="[^"]+mm"/,`height="${h}"`);
  const url="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(t);
  try{const im=new Image();await new Promise((res,rej)=>{im.onload=res;im.onerror=()=>rej(Error("位图渲染失败。"));im.src=url});
    if(im.decode)await im.decode().catch(()=>{});
    const cv=document.createElement("canvas");cv.width=w;cv.height=h;const ctx=cv.getContext("2d");
    if(!transparent){ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h)}ctx.drawImage(im,0,0,w,h);return cv}
  finally{}
}
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1}return(c^0xffffffff)>>>0}
function pngDPI(bytes,d){const ch=new Uint8Array(21),dv=new DataView(ch.buffer);dv.setUint32(0,9);ch.set([112,72,89,115],4);dv.setUint32(8,Math.round(d/.0254));dv.setUint32(12,Math.round(d/.0254));ch[16]=1;dv.setUint32(17,crc32(ch.subarray(4,17)));
  const parts=[bytes.subarray(0,8)];let pos=8;while(pos<bytes.length){const len=new DataView(bytes.buffer,bytes.byteOffset+pos,4).getUint32(0),type=String.fromCharCode(...bytes.subarray(pos+4,pos+8));if(type!=="pHYs")parts.push(bytes.subarray(pos,pos+len+12));if(type==="IHDR")parts.push(ch);pos+=len+12}
  const out=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}
function jpegDPI(bytes,d){for(let i=2;i<Math.min(bytes.length-16,2000);i++){if(bytes[i]===0xff&&bytes[i+1]===0xe0&&String.fromCharCode(...bytes.slice(i+4,i+9))==="JFIF\0"){bytes[i+11]=1;bytes[i+12]=d>>8;bytes[i+13]=d&255;bytes[i+14]=d>>8;bytes[i+15]=d&255;return bytes}}
  const app=new Uint8Array([255,224,0,16,74,70,73,70,0,1,1,1,d>>8,d&255,d>>8,d&255,0,0]),out=new Uint8Array(bytes.length+app.length);out.set(bytes.slice(0,2));out.set(app,2);out.set(bytes.slice(2),2+app.length);return out}
function bitmapFile(cv,d,format){
  const w=cv.width,h=cv.height,rgba=cv.getContext("2d").getImageData(0,0,w,h).data;
  if(format==="bmp"){const stride=(w*3+3)&~3,size=54+stride*h,out=new Uint8Array(size),dv=new DataView(out.buffer);out.set([66,77]);dv.setUint32(2,size,true);dv.setUint32(10,54,true);dv.setUint32(14,40,true);dv.setInt32(18,w,true);dv.setInt32(22,h,true);dv.setUint16(26,1,true);dv.setUint16(28,24,true);dv.setUint32(34,stride*h,true);dv.setInt32(38,Math.round(d/.0254),true);dv.setInt32(42,Math.round(d/.0254),true);
    for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*4,j=54+(h-1-y)*stride+x*3;out[j]=rgba[i+2];out[j+1]=rgba[i+1];out[j+2]=rgba[i]}return out}
  const count=13,extra=8+2+count*12+4,bits=extra,xres=extra+6,yres=extra+14,start=extra+22,out=new Uint8Array(start+w*h*3),dv=new DataView(out.buffer);
  out.set([73,73,42,0]);dv.setUint32(4,8,true);dv.setUint16(8,count,true);
  const tags=[[256,4,1,w],[257,4,1,h],[258,3,3,bits],[259,3,1,1],[262,3,1,2],[273,4,1,start],[277,3,1,3],[278,4,1,h],[279,4,1,w*h*3],[282,5,1,xres],[283,5,1,yres],[284,3,1,1],[296,3,1,2]];
  tags.forEach((a,i)=>{const o=10+i*12;dv.setUint16(o,a[0],true);dv.setUint16(o+2,a[1],true);dv.setUint32(o+4,a[2],true);if(a[1]===3&&a[2]===1)dv.setUint16(o+8,a[3],true);else dv.setUint32(o+8,a[3],true)});
  for(let i=0;i<3;i++)dv.setUint16(bits+i*2,8,true);for(const o of [xres,yres]){dv.setUint32(o,Math.round(d*1000),true);dv.setUint32(o+4,1000,true)}
  for(let i=0,j=start;i<rgba.length;i+=4){out[j++]=rgba[i];out[j++]=rgba[i+1];out[j++]=rgba[i+2]}return out;
}
function download(content,name,type){
  // 一般大小的文件用 data 地址下载（有些预览环境不支持 blob 地址）；超过 300 MB 才用 blob
  const bytes=content instanceof Uint8Array?content:content instanceof ArrayBuffer?new Uint8Array(content):typeof content==="string"?new TextEncoder().encode(content):null;
  const slot=$("#dlSlot");const old=slot.querySelector("a");if(old&&old.href.startsWith("blob:"))URL.revokeObjectURL(old.href);
  const a=document.createElement("a");
  if(bytes&&bytes.length<300e6)a.href="data:"+(type||"application/octet-stream")+";base64,"+bytesToB64(bytes);
  else a.href=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));
  a.download=name;a.className="dl";a.textContent="未自动下载？点此保存";a.title=name;
  slot.replaceChildren(a);a.click();
}
function defaultFileName(){const src=String(source||"").replace(/\.(pdf|json)$/i,"").trim();return src?"IsoStyle_"+src:"IsoStyle"}
function baseName(){const n=(S.exp.name||defaultFileName()).split("\n")[0].replace(/[\^_]\{([^}]*)\}/g,"$1").replace(/[\\/:*?"<>|]+/g,"_").replace(/[\s·]+/g,"_").replace(/_+/g,"_").replace(/^_|_$/g,"");return n||"IsoStyle"}
// jsPDF + svg2pdf 只在第一次导出 PDF 时解压加载
let libsP=null;
function loadScriptBytes(bytes){runScriptText(bytes);return Promise.resolve()}
function loadPDFLibs(){return libsP||(libsP=(async()=>{if(!window.jspdf)await loadScriptBytes(await gunzipB64("jspdfLib"));await loadScriptBytes(await gunzipB64("svg2pdfLib"));if(!window.jspdf||!window.jspdf.jsPDF||!window.jspdf.jsPDF.API.svg){libsP=null;throw Error("PDF 导出组件加载失败。")}})())}
async function makePDF(){
  await loadPDFLibs();
  const {jsPDF}=window.jspdf;
  const pdf=new jsPDF({orientation:dims.W>dims.H?"landscape":"portrait",unit:"pt",format:[dims.W,dims.H],putOnlyUsedFonts:true,compress:true});
  const c=cleanSVG();
  // PDF 里的字体名用真实字体名（Inter / LiberationSans / LiberationSerif），在 Illustrator 里更好认
  const PDF_NAME={Inter:"Inter",Arial:"LiberationSans",Times:"LiberationSerif"};
  for(const f of usedFonts(c.outerHTML)){const fn=PDF_NAME[f.fam]+"-"+f.s+".ttf";pdf.addFileToVFS(fn,fontB64(f.fam,f.s));pdf.addFont(fn,PDF_NAME[f.fam],f.s)}
  c.querySelectorAll("[font-family]").forEach(n=>{const k=Object.keys(FAMILY).find(k=>FAMILY[k]===n.getAttribute("font-family"));if(k)n.setAttribute("font-family",PDF_NAME[k])});
  c.setAttribute("width",dims.W);c.setAttribute("height",dims.H);
  await pdf.svg(c,{x:0,y:0,width:dims.W,height:dims.H});
  pdf.setProperties({title:baseName(),creator:"IsoStyle v2.5.3"});
  return pdf.output("arraybuffer");
}
async function doExport(){
  if(!draw())return;const b=$("#expBtn");b.disabled=true;hdr("正在生成…");
  try{await document.fonts.ready;
    const f=S.exp.format,name=baseName(),transparent=S.exp.bg==="none"&&["png","webp","svg"].includes(f);
    if(f==="svg")download(exportSVGText(S.exp.embed,transparent?"none":"white"),name+".svg","image/svg+xml");
    else if(f==="pdf")download(await makePDF(),name+".pdf","application/pdf");
    else{const d=dpi(),cv=await rasterCanvas(d,transparent);
      if(f==="tiff"||f==="bmp")download(bitmapFile(cv,d,f),name+(f==="tiff"?".tif":".bmp"),f==="tiff"?"image/tiff":"image/bmp");
      else{const type="image/"+f,blob=await new Promise(res=>cv.toBlob(res,type,.95));
        if(!blob||blob.type!==type)throw Error("这个浏览器不支持导出 "+f.toUpperCase()+"。");
        let bytes=new Uint8Array(await blob.arrayBuffer());if(f==="png")bytes=pngDPI(bytes,d);if(f==="jpeg")bytes=jpegDPI(bytes,d);
        download(bytes,name+"."+(f==="jpeg"?"jpg":f),type)}}
    hdr("已导出 "+f.toUpperCase());
  }catch(e){showMsg("导出失败："+e.message,true);hdr("")}finally{b.disabled=false}
}
$("#expBtn").onclick=doExport;
$("#expToggle").onclick=()=>{const m=$("#expMore"),open=m.hidden;m.hidden=!open;$("#expToggle").setAttribute("aria-expanded",open);$("#expToggle").classList.toggle("on",open);quietDraw++;try{draw()}finally{quietDraw--}};
$("#saveBtn").onclick=()=>{
  if(!raw){hdr("还没有数据");return}
  const p={isoStyle:3,data:raw,fields:{x:FX,y:FY},S,groups,order,pdfResult,source,jsonName,pdfBytes:pdfBytes?bytesToB64(pdfBytes):null};
  const t=new Date(),hms=[t.getHours(),t.getMinutes(),t.getSeconds()].map(v=>String(v).padStart(2,"0")).join("");
  const nm=String(jsonName||source||"data").replace(/\.(json|pdf)$/i,"").replace(/[\\/:*?"<>|]+/g,"_").replace(/\s+/g,"_");
  download(JSON.stringify(p),`IsoStyle_${nm}_${hms}.json`,"application/json");hdr("项目已保存");setDirty(false,true);
};
